import "core-js/modules/es.array.push.js";
/* eslint-disable */

export default {
  props: {
    ViewInfo: Object
  },
  data() {
    return {
      locationAddress: "",
      geoLongitude: "",
      geoLattitude: "",
      // locationName: "",
      pincode: "",
      search: "",
      currentPlace: null,
      markers: [],
      defaultCenter: {
        lat: 0,
        lng: 0
      },
      latt: "",
      longg: "",
      loading: false
    };
  },
  mounted() {
    if (this.ViewInfo) {
      this.geoLongitude = this.ViewInfo.location_long || "";
      this.geoLattitude = this.ViewInfo.location_lat || "";
      this.locationAddress = this.ViewInfo.location_address || "";
      this.pincode = this.ViewInfo.location_pincode || "";
    }
  },
  created() {
    this.markers = [];
  },
  watch: {
    geoLattitude(newLat) {
      if (newLat && this.geoLongitude) {
        this.updateMap();
      }
    },
    geoLongitude(newLng) {
      if (newLng && this.geoLattitude) {
        this.updateMap();
      }
    }
  },
  methods: {
    updateMap() {
      const lat = parseFloat(this.geoLattitude);
      const lng = parseFloat(this.geoLongitude);
      if (!isNaN(lat) && !isNaN(lng)) {
        this.center = {
          lat,
          lng
        };
        this.markers = [{
          position: {
            lat,
            lng
          }
        }];
      }
    },
    is_number(evt) {
      evt = evt ? evt : window.event;
      var charCode = evt.which ? evt.which : evt.keyCode;
      if (charCode > 31 && (charCode < 48 || charCode > 57) && charCode !== 46) {
        evt.preventDefault();
      } else {
        return true;
      }
    },
    back_action() {
      this.$emit("backtofirstStep", 1);
    },
    emit_third_step() {
      if (this.$refs.form.validate()) {
        var data = {
          // locationName: this.locationName,
          geoLattitude: this.geoLattitude.toString(),
          geoLongitude: this.geoLongitude.toString(),
          locationsAddress: this.locationAddress,
          pincode: Number(this.pincode)
        };
        this.$emit("emitThirdSTep", data);
      }
    },
    setPlace(place) {
      this.currentPlace = place;
    },
    clearField() {
      this.search = null;
      this.addMarker();
    },
    addMarker() {
      if (this.currentPlace) {
        this.locationAddress = this.currentPlace.formatted_address;
        this.markers = [];
        var marker = {
          lat: this.currentPlace.geometry.location.lat(),
          lng: this.currentPlace.geometry.location.lng()
        };
        this.markers.push({
          position: marker
        });
        this.geoLattitude = marker.lat, this.geoLongitude = marker.lng;
      }
    },
    callposition(latLng) {
      this.markers = [];
      var marker = {
        lat: latLng.latLng.lat(),
        lng: latLng.latLng.lng()
      };
      this.markers.push({
        position: marker
      });
      this.geoLattitude = marker.lat, this.geoLongitude = marker.lng;
    }
  }
};
